def clean(df):
    df = df.copy()
    # Drop rows with invalid negative quantity (rule: min 1)
    df = df[df['Quantity'] >= 1].copy()
    # Recalculate Revenue to ensure consistency with formula
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

